import java.util.*;import java.nio.charset.*;
class MountainBlockExportTest{public static void main(String[]args)throws Exception{for(int m:new int[]{12,17,18}){int expected=1000000+m-10;for(int y:new int[]{200,195,180,152})if(ExportBlocks.block(200,m,62,0,0,0,y,3)!=expected)throw new AssertionError("Mountain material lost on exposed face at "+y);if(ExportBlocks.block(200,m,62,0,0,0,151,3)!=3)throw new AssertionError("Missing deep stone");if(ExportBlocks.block(200,m,62,4,0,0,201,3)!=16)throw new AssertionError("Snow layer changed");}var w=new TerraForge.World(32,62,71);Arrays.fill(w.height,200);w.environment.material=new byte[1024];Arrays.fill(w.environment.material,(byte)18);String chunk=new String(TerraForge.chunk(w,0,0),StandardCharsets.ISO_8859_1);int occurrences=chunk.split("minecraft:granite",-1).length-1;if(occurrences<4)throw new AssertionError("Chunk section optimization erased rock layers: "+occurrences);try(var assets=new MinecraftAssets(MinecraftAssets.locate())){for(int m:new int[]{3,12,17,18})if(assets.block(ExportBlocks.block(200,m,62,0,0,0,170)).faces().isEmpty())throw new AssertionError("Missing vanilla model");if(assets.missingTextures!=0)throw new AssertionError("Missing vanilla texture");}System.out.println("PASS: vanilla mountain rock survives 48-block exposed faces, section export and snow layers; deep substrate remains stone; vanilla textures load");}}
